SELECT COUNT(1)
FROM exp_tender_evaluation
WHERE CONCAT('ROUND-', round_no) = #{committeeCode}

    AND eval_id != #{excludeCommitteeId}

SELECT COALESCE(MAX(round_no), 0)
FROM exp_tender_evaluation
WHERE tender_id = #{tenderId}

SELECT

FROM exp_tender_evaluation c
LEFT JOIN exp_tender t ON c.tender_id = t.tender_id


        AND c.tender_id = #{req.tenderId}


        AND CONCAT('ROUND-', c.round_no) LIKE CONCAT('%', #{req.committeeCode}, '%')


        AND CONCAT('第', c.round_no, '轮评标') LIKE CONCAT('%', #{req.committeeName}, '%')


        AND c.stage_code = #{req.evaluationMethod}


        AND c.result = #{req.status}


        AND c.evaluator_user_id = #{req.evaluationDirectorId}


        AND c.eval_time >= #{req.evaluationStartTimeStart}


        AND c.eval_time <= #{req.evaluationStartTimeEnd}


        AND c.evaluator_user_id = #{req.createdBy}


        AND c.eval_time >= #{req.createdTimeStart}


        AND c.eval_time <= #{req.createdTimeEnd}


ORDER BY c.eval_time DESC

